// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "https://github.com/AmazingAng/WTF-Solidity/blob/main/34_ERC721/ERC721.sol";


/**
 * @dev 验证Merkle树的合约.
 *
 * proof可以用JavaScript库生成：
 * https://github.com/miguelmota/merkletreejs[merkletreejs].
 * 注意: hash用keccak256，并且开启pair sorting （排序）.
 * javascript例子见 `https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/test/utils/cryptography/MerkleProof.test.js`.
 */

library MerkelProof {

    /**
     * @dev 当通过`proof`和`leaf`重建出的`root`与给定的`root`相等时，返回`true`，数据有效。
     * 在重建时，叶子节点对和元素对都是排序过的。
     */
    function verify(bytes32[] memory proof, bytes32 root, bytes32 leaf) internal pure returns (bool) {
        return processProof(proof, leaf) == root;
    }

    /**
     * @dev Returns 通过Merkle树用`leaf`和`proof`计算出`root`. 当重建出的`root`和给定的`root`相同时，`proof`才是有效的。
     * 在重建时，叶子节点对和元素对都是排序过的。
     */
    function processProof(bytes32[] memory proof, bytes32 leaf) internal pure returns (bytes32) {
        
        bytes32 computerHash = leaf;
        for (uint i=0; i < proof.length; i++) {
            computerHash = hashPair(computerHash, proof[i]);
        }

        return computerHash;
    }

    // Sorted Pair Hash
    function hashPair(bytes32 a, bytes32 b) private pure returns (bytes32) {
        return a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
    }

}


contract MerkleTree is ERC721 {

    bytes32 immutable public root; // Merkle树的根
    mapping(address => bool) public mintedAddress;   // 记录已经mint的地址


    // 构造函数，初始化NFT合集的名称、代号、Merkle树的根
    constructor (string memory name , string memory  symbol, bytes32 markelRoot) ERC721(name, symbol) {
        root = markelRoot;
    }
 
    // 利用Merkle树验证地址并完成mint
    function mint(address account, uint256 tokenId, bytes32[] calldata proof) external {

        // Merkle检验通过
        require(_verify(_leaf(account), proof), "You are not in the Merkle tree");

        // 地址没有mint过
        require(!mintedAddress[account], "You have already minted");

        // 记录mint过的地址
        mintedAddress[account] = true;

        // mint
        _mint(account, tokenId);

    }

    // 计算Merkle书叶子的哈希值
    function _leaf(address account) private pure returns (bytes32) {
        return keccak256(abi.encodePacked(account));
    }

    // Merkle树验证，调用MerkleProof库的verify()函数
    function _verify(bytes32 leaf, bytes32[] calldata proof) private view returns(bool) {
        return MerkelProof.verify(proof, root, leaf);
    }

}

